ALTER TABLE "chat_research_artifacts" DROP CONSTRAINT "chat_research_artifacts_retention";--> statement-breakpoint
ALTER TABLE "chat_research_maintenance" DROP CONSTRAINT "chat_research_maintenance_coverage";--> statement-breakpoint
ALTER TABLE "chat_research_maintenance" DROP CONSTRAINT "chat_research_maintenance_terminal";--> statement-breakpoint
ALTER TABLE "chat_research_artifacts" ADD CONSTRAINT "chat_research_artifacts_retention" CHECK (pg_catalog.isfinite("chat_research_artifacts"."job_created_at") and pg_catalog.isfinite("chat_research_artifacts"."stored_at") and pg_catalog.isfinite("chat_research_artifacts"."retain_until") and ("chat_research_artifacts"."purged_at" is null or pg_catalog.isfinite("chat_research_artifacts"."purged_at")) and ("chat_research_artifacts"."retain_until"="chat_research_artifacts"."job_created_at"+interval '720 hours' or "chat_research_artifacts"."retain_until"="chat_research_artifacts"."job_created_at"+interval '48 hours') and "chat_research_artifacts"."stored_at">="chat_research_artifacts"."job_created_at" and "chat_research_artifacts"."stored_at"<"chat_research_artifacts"."retain_until");--> statement-breakpoint
ALTER TABLE "chat_research_maintenance" ADD CONSTRAINT "chat_research_maintenance_coverage" CHECK (pg_catalog.isfinite("chat_research_maintenance"."publication_cutoff") and "chat_research_maintenance"."publication_cutoff">=timestamptz '1970-01-01T00:00:00Z' and pg_catalog.isfinite("chat_research_maintenance"."coverage_through") and ("chat_research_maintenance"."coverage_through"="chat_research_maintenance"."publication_cutoff"+interval '721 hours' or "chat_research_maintenance"."coverage_through"="chat_research_maintenance"."publication_cutoff"+interval '54 hours'));--> statement-breakpoint
ALTER TABLE "chat_research_maintenance" ADD CONSTRAINT "chat_research_maintenance_terminal" CHECK (("chat_research_maintenance"."state"<>'healthy' or ("chat_research_maintenance"."expired_packets"=0 and ("chat_research_maintenance"."latest_retain_until" is null or "chat_research_maintenance"."latest_retain_until"<="chat_research_maintenance"."coverage_through"-(case when "chat_research_maintenance"."coverage_through"="chat_research_maintenance"."publication_cutoff"+interval '54 hours' then interval '6 hours' else interval '1 hour' end)))) and ("chat_research_maintenance"."state"<>'closed' or "chat_research_maintenance"."unpurged_packets"=0));